const incoming = $input.all().map(i => i.json);
let rows = [];
if (incoming.length === 1 && Array.isArray(incoming[0].results)) rows = incoming[0].results;
else rows = incoming;

const expected = Array.from({length:10}, (_,i)=>'runtime-' + String(i+1).padStart(2,'0'));
const errors = [];
const byId = new Map();
for (const row of rows) {
  if (!row || typeof row !== 'object') { errors.push('INVALID_RESULT'); continue; }
  if (byId.has(row.runtime_id)) errors.push('DUPLICATE_RUNTIME:' + row.runtime_id);
  byId.set(row.runtime_id, row);
}
for (const id of expected) if (!byId.has(id)) errors.push('MISSING_RUNTIME:' + id);

for (const id of expected) {
  const row = byId.get(id);
  if (!row) continue;
  const checks = [
    row.schema === 'OGE62_FLOW_RUNTIME_RESULT_V1',
    row.state === 'PROVISIONAL_DONE',
    row.provisional_done === true,
    row.final_done === false,
    row.self_verify === 'PASS',
    row.provider_call_attempted === false,
    row.paid_call_performed === false,
    row.canonical_write_attempted === false,
    row.d1_schema_write_attempted === false,
    row.secret_values_included === false,
    row.policy?.auto_retry === false,
    Number(row.policy?.attempt_budget) === 1,
    row.policy?.clone_close_scope === 'OWN_PROVISIONAL_RESULT_ONLY'
  ];
  if (!checks.every(Boolean)) errors.push('PREAUDIT_FAIL:' + id);
}
if (rows.length !== 10) errors.push('EXPECTED_10_RESULTS:FOUND_' + rows.length);
const taskFingerprints = new Set(rows.map(r=>r?.task_fingerprint).filter(Boolean));
if (taskFingerprints.size !== 1) errors.push('TASK_FINGERPRINT_MISMATCH');
const evidenceDigests = rows.map(r=>r?.evidence_digest).filter(Boolean);
if (evidenceDigests.length !== 10 || new Set(evidenceDigests).size !== 10) errors.push('EVIDENCE_DIGEST_INVALID');

const ok = errors.length === 0;
return [{json:{
  schema:'OGENIC_N8N_OGE62_PREAUDIT_V1',
  ok,
  state: ok ? 'AUDIT_PENDING' : 'REWORK_REQUIRED',
  provisional_done_count: rows.filter(r=>r?.state==='PROVISIONAL_DONE').length,
  expected_runtime_count:10,
  github_audit_required:true,
  yellow_commit_gate_required:true,
  ruby_semantic_gate_required:true,
  green_retention_allowed:false,
  errors,
  results: rows.map(r=>({
    runtime_id:r.runtime_id,
    revision:r.revision,
    execution_profile:r.execution_profile,
    task_fingerprint:r.task_fingerprint,
    evidence_digest:r.evidence_digest,
    self_verify:r.self_verify,
    state:r.state
  }))
}}];

const x=$json;
return [{json:{
  ...x,
  handoff:{
    target:'GITHUB_ACTIONS_DETERMINISTIC_AUDIT',
    workflow:'.github/workflows/oge-62-flow-audit-commit.yml',
    commit_eligible:false,
    reason:x.ok ? 'N8N_PREAUDIT_PASS_GITHUB_RECHECK_REQUIRED' : 'N8N_PREAUDIT_FAIL_REWORK_REQUIRED'
  },
  authority:{
    n8n:'PREAUDIT_ONLY',
    github:'DETERMINISTIC_AUDIT',
    yellow:'FINAL_EXECUTION_AND_COMMIT_GATE',
    ruby:'SEMANTIC_VERIFY',
    green:'FINAL_DONE_RETENTION_ONLY'
  }
}}];
